using Payments;

namespace PaymentGateway.Tests;

[TestClass]
public sealed class PaymentGatewayChargeAsyncTests
{
    private Payments.PaymentGateway _sut = null!;

    [TestInitialize]
    public void SetUp()
    {
        _sut = new Payments.PaymentGateway();
    }

    // ── Happy-path: valid charge attempts ──────────────────────────────

    [TestMethod]
    public async Task ChargeAsync_ValidTokenAndPositiveAmount_ThrowsNotImplementedException()
    {
        // Arrange
        var cardToken = "tok_valid_visa";
        var amount = 49.99m;

        // Act & Assert
        await Assert.ThrowsExactlyAsync<NotImplementedException>(
            () => _sut.ChargeAsync(cardToken, amount));
    }

    [TestMethod]
    [DataRow("tok_mastercard_123", 1.00, DisplayName = "Minimum realistic charge")]
    [DataRow("tok_amex_456", 999.99, DisplayName = "Large charge amount")]
    [DataRow("tok_discover_789", 0.01, DisplayName = "Smallest positive amount")]
    public async Task ChargeAsync_VariousValidTokensAndAmounts_ThrowsNotImplementedException(
        string cardToken, double amountDouble)
    {
        // Arrange
        var amount = (decimal)amountDouble;

        // Act & Assert
        await Assert.ThrowsExactlyAsync<NotImplementedException>(
            () => _sut.ChargeAsync(cardToken, amount));
    }

    // ── Edge cases: null and empty tokens ──────────────────────────────

    [TestMethod]
    public async Task ChargeAsync_NullToken_ThrowsNotImplementedException()
    {
        // Arrange
        string cardToken = null!;
        var amount = 10.00m;

        // Act & Assert — current behavior throws NotImplementedException for any input
        await Assert.ThrowsExactlyAsync<NotImplementedException>(
            () => _sut.ChargeAsync(cardToken, amount));
    }

    [TestMethod]
    [DataRow("", DisplayName = "Empty string token")]
    [DataRow("   ", DisplayName = "Whitespace-only token")]
    public async Task ChargeAsync_EmptyOrWhitespaceToken_ThrowsNotImplementedException(
        string cardToken)
    {
        // Arrange
        var amount = 25.00m;

        // Act & Assert
        await Assert.ThrowsExactlyAsync<NotImplementedException>(
            () => _sut.ChargeAsync(cardToken, amount));
    }

    // ── Edge cases: zero and negative amounts ──────────────────────────

    [TestMethod]
    public async Task ChargeAsync_ZeroAmount_ThrowsNotImplementedException()
    {
        // Arrange
        var cardToken = "tok_valid";
        var amount = 0m;

        // Act & Assert
        await Assert.ThrowsExactlyAsync<NotImplementedException>(
            () => _sut.ChargeAsync(cardToken, amount));
    }

    [TestMethod]
    [DataRow(-0.01, DisplayName = "Smallest negative amount")]
    [DataRow(-100.00, DisplayName = "Large negative amount")]
    public async Task ChargeAsync_NegativeAmount_ThrowsNotImplementedException(
        double amountDouble)
    {
        // Arrange
        var cardToken = "tok_valid";
        var amount = (decimal)amountDouble;

        // Act & Assert
        await Assert.ThrowsExactlyAsync<NotImplementedException>(
            () => _sut.ChargeAsync(cardToken, amount));
    }

    // ── Boundary values ────────────────────────────────────────────────

    [TestMethod]
    public async Task ChargeAsync_MaxDecimalAmount_ThrowsNotImplementedException()
    {
        // Arrange
        var cardToken = "tok_valid";
        var amount = decimal.MaxValue;

        // Act & Assert
        await Assert.ThrowsExactlyAsync<NotImplementedException>(
            () => _sut.ChargeAsync(cardToken, amount));
    }

    [TestMethod]
    public async Task ChargeAsync_VerySmallPositiveAmount_ThrowsNotImplementedException()
    {
        // Arrange
        var cardToken = "tok_valid";
        var amount = 0.001m;

        // Act & Assert
        await Assert.ThrowsExactlyAsync<NotImplementedException>(
            () => _sut.ChargeAsync(cardToken, amount));
    }
}

