[TestClass]
public sealed class ChargeResultTests
{
    [TestMethod]
    public void ChargeResult_Constructor_StoresChargeIdAndSuccess()
    {
        // Arrange & Act
        var result = new ChargeResult("ch_test_123", true);

        // Assert
        Assert.AreEqual("ch_test_123", result.ChargeId);
        Assert.IsTrue(result.Success);
    }

    [TestMethod]
    public void ChargeResult_ConstructorWithFailure_StoresValues()
    {
        // Arrange & Act
        var result = new ChargeResult("ch_fail_456", false);

        // Assert
        Assert.AreEqual("ch_fail_456", result.ChargeId);
        Assert.IsFalse(result.Success);
    }

    [TestMethod]
    public void ChargeResult_EqualityByValue_TwoIdenticalRecordsAreEqual()
    {
        // Arrange
        var result1 = new ChargeResult("ch_eq", true);
        var result2 = new ChargeResult("ch_eq", true);

        // Assert
        Assert.AreEqual(result1, result2);
    }

    [TestMethod]
    public void ChargeResult_Inequality_DifferentChargeIdsAreNotEqual()
    {
        // Arrange
        var result1 = new ChargeResult("ch_a", true);
        var result2 = new ChargeResult("ch_b", true);

        // Assert
        Assert.AreNotEqual(result1, result2);
    }

    [TestMethod]
    public void ChargeResult_Inequality_DifferentSuccessValuesAreNotEqual()
    {
        // Arrange
        var result1 = new ChargeResult("ch_same", true);
        var result2 = new ChargeResult("ch_same", false);

        // Assert
        Assert.AreNotEqual(result1, result2);
    }
}

